CREATE OR REPLACE FUNCTION public.save_team_member(p_client_id uuid, p_member_id uuid, p_name text, p_role text, p_email text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare uid uuid;mid uuid;old_uid uuid;
begin
 if not private.is_admin() then raise exception 'Accès administrateur requis'; end if;
 if length(trim(p_name)) not between 1 and 150 or p_role not in ('Responsable','Membre') then raise exception 'Nom ou rôle invalide'; end if;
 if not exists(select 1 from public.clients where id=p_client_id and work_mode='Équipe') then raise exception 'Activez le mode Équipe sur ce dossier'; end if;
 if trim(coalesce(p_email,''))<>'' then select id into uid from public.profiles where lower(email)=lower(trim(p_email)); if uid is null then raise exception 'Créez d’abord l’accès de cette personne au portail, ou laissez le courriel vide pour préparer sa fiche'; end if; end if;
 if p_member_id is not null then
  select user_id into old_uid from public.team_members where id=p_member_id and client_id=p_client_id for update;
  if not found then raise exception 'Membre introuvable'; end if;
  if old_uid is not null and uid is not null and old_uid<>uid then raise exception 'Cet accès est déjà associé à une autre personne'; end if;
  update public.team_members set name=trim(p_name),team_role=p_role,user_id=coalesce(old_uid,uid) where id=p_member_id returning id into mid;
 else insert into public.team_members(client_id,user_id,name,team_role) values(p_client_id,uid,trim(p_name),p_role) returning id into mid; end if;
 if uid is not null then insert into public.client_memberships(client_id,user_id) values(p_client_id,uid) on conflict do nothing; end if;
 return mid;
end; $function$
